class Solution:
    def search(self, nums: List[int], target: int) -> int:
        if nums[0] == target:
            return 0
            
        l, r = 0, len(nums) - 1

        while l < r:
            m = (l+r) // 2
            if target == nums[l]:
                return l
            if target == nums[m]:
                return m
            if target == nums[r]:
                return r
            if nums[l] <= nums[m] <= nums[r]:
                if target > nums[m]:
                    l = m + 1
                else:
                    r = m - 1
            elif nums[l] <= nums[m] and nums[r] <= nums[m]:
                if nums[l] < target < nums[m]:
                    r = m - 1
                else:
                    l = m + 1
            elif nums[m] <= nums[l] and nums[m] <= nums[r]:
                if nums[m] < target < nums[r]:
                    l = m + 1
                else:
                    r = m - 1
        return -1

